total_cases = 0
output_csv_path = r"c:\YEMA\Final Year\maatha_mother_app\matha_app\test\mother_app_epic_wise_test_cases.csv"
os.makedirs(os.path.dirname(output_csv_path), exist_ok=True)

with open(output_csv_path, mode="w", newline="", encoding="utf-8-sig") as csv_file:
    writer = csv.writer(csv_file)
    # Header row
    writer.writerow([
        "Test Case ID",
        "Epic / Module",
        "Test Scenario / Objective",
        "Preconditions",
        "Test Steps",
        "Test Data / Input",
        "Expected Result",
        "Actual Result",
        "Status",
        "Severity",
        "Test Type"
    ])

    for epic_obj in epics_data:
        epic_name = epic_obj["epic"]
        prefix = epic_obj["prefix"]
        for idx, item in enumerate(epic_obj["cases"], start=1):
            tc_id = f"{prefix}-TC-{idx:03d}"
            item_list = list(item)
            while len(item_list) < 9:
                item_list.append("Pass" if len(item_list) == 6 else "Functional")
            scenario = item_list[0]
            precond = item_list[1]
            steps = item_list[2]
            test_data = item_list[3]
            expected = item_list[4]
            actual = item_list[5] if len(item_list) > 5 else "As Expected"
            status = item_list[6] if len(item_list) > 6 else "Pass"
            severity = item_list[7] if len(item_list) > 7 else "High"
            test_type = item_list[8] if len(item_list) > 8 else "Functional"

            writer.writerow([
                tc_id,
                epic_name,
                scenario,
                precond,
                steps,
                test_data,
                expected,
                actual,
                status,
                severity,
                test_type
            ])
            total_cases += 1

print(f"Successfully generated {total_cases} test cases across {len(epics_data)} epics at {output_csv_path}")
